head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gPROCS_CD = '';
scwin.V_PROCS_CD_2 = '2'; // 검토
scwin.V_PROCS_CD_3 = '3'; // 승인
scwin.V_PROCS_CD_4 = '4'; // 거부
scwin.gLinkApplSeq;
scwin.gLinkListStatCd;
scwin.gDepCd = js_dep_cd;
scwin.gDutyYn = js_duty;
scwin.gDutyChrg = js_duty_chrg; // 세션정보
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        scwin.getParentValue();
        scwin.init();
        await scwin.readSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF33011.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    const gMsg = "" + "① 지주회사의 신청내용을 근거로 하여서만 상장자회사의 수시공시 내용이 지주회사 종목공시에 연계하여  \n" + "    공표되므로, 연계공시 신청서 작성시 착오가 발생하지 않도록 주의하시기 바라며, 변동사실＊ 발생시에는  \n" + "    동 사실을 즉시 정정하여 신청서를 제출하여야 함  \n" + "    ＊ 변동사실 \n" + "       가. 상장 여부의 변동, 상장된 증권시장의 이동 등 \n" + "       나. 지주회사가 소유하고 있는 상장자회사 주식의 최근 사업연도말 재무제표상 가액이 지주회사의  \n" + "            최근 사업연도말 자산총액의 10% 이상․미만 등  \n" + "② 상장자회사의 변동사실을 거래소에 미신고함으로써 발생하는 모든 책임은 지주회사에게 있음\n" + "③ 정정공시의 경우에는 연계공시 적용일 이후의 공시내용이 정정되는 경우에 한하여만 연계공표되므로 \n" + "    적용일 이전의 상장자회사가 제출한 수시공시 내용에 대한 정정공시에 대하여는 지주회사가 이를 \n" + "    별도로 제출하여야 함 \n" + "④ 지주회사-자회사간 상장된 증권시장이 상이한 경우에는 자회사 공시내용의 지주회사 연계공표시 자회사가 \n" + "     상장된 증권시장을 기준으로 생성됨을 원칙으로 함 \n" + "⑤ 연계공시 신청에 의하여 상장자회사의 수시공시 내용이 지주회사의 별도 공시제출없이 증권시장에 공표된 경우, \n" + "    연계공시 내용에 대한 지주회사의 공시내용 정정을 위한 수정․편집 기능은 제공하지 않음 \n" + "⑥ 연계공시 신청에 의하여 상장자회사의 수시공시 내용이 지주회사의 별도 공시제출없이 증권시장에 공표된 경우, \n" + "    상장자회사가 수시공시 내용을 철회(또는 삭제)한 경우에 한하여만 지주회사의 연계공시 내용에 대한 \n" + "    철회(또는 삭제)가 가능함";
    txa_Noti.Text = gMsg;
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_Item_OnLoadError
 * @description dts_Item 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Item_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Item);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF33011.dts_Item_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Check_OnLoadError
 * @description dts_Check 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Check_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Check);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF33011.dts_Check_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Item_OnLoadCompleted
 * @description dts_Item 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Item_OnLoadCompleted = function(rowcount) {
    try {
        scwin.showProcButton(dts_Item.getCellData(1, "HDCOM_DEP_CD"), dts_Item.getCellData(1, "LNK_DISCLS_PROCS_STAT_CD"));
        panel_BF_OVR10PCT_YN.hide();
        panel_AF_OVR10PCT_YN.hide();
        if (dts_Item.getCellData(1, "LNK_DISCLS_APPL_TP_CD") === '2') {
            panel_BF_OVR10PCT_YN.show("");
            panel_AF_OVR10PCT_YN.show("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33011.dts_Item_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_LNK_DISCLS_APPL_DD_onclick
 * @description img_LNK_DISCLS_APPL_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_LNK_DISCLS_APPL_DD_onclick = function() {
    try {
        popUpCalendar2(edt_LNK_DISCLS_APPL_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33011.img_LNK_DISCLS_APPL_DD_onclick" });
    }
};

/**
 * @method
 * @name trs_Approve_OnSuccess
 * @description Approve On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Approve_OnSuccess = async function() {
    try {
        await $c.win.alert('정상처리되었습니다');
        await scwin.readSync();
        $c.frame.path("../").fn_list_sync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF33011.trs_Approve_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Approve_OnFail
 * @description Approve On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Approve_OnFail = async function() {
    try {
        await $c.win.alert('처리가 실패하였습니다');
        await $c.win.alert(trs_Approve.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF33011.trs_Approve_OnFail" });
    }
};

/**
 * @method
 * @name btn_Revwr_onclick
 * @description 「검토」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Revwr_onclick = async function() {
    try {
        await scwin.revwr();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF33011.btn_Revwr_onclick" });
    }
};

/**
 * @method
 * @name btn_Approve_onclick
 * @description 「승인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Approve_onclick = async function() {
    try {
        await scwin.approve();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF33011.btn_Approve_onclick" });
    }
};

/**
 * @method
 * @name btn_Reject_onclick
 * @description 「거부」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Reject_onclick = async function() {
    try {
        await scwin.reject();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF33011.btn_Reject_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        $c.frame.path("../").fn_list_sync();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF33011.btn_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name readSync
 * @description read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function() {
    url += "&SCREN_ID=" + "ULDSTF33011.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Item",
        action : "/LnkDisclsApplCorp.do",
        ref : "",
        target : "dts_Item=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name getProcsSate
 * @description 처리상태 조회하기
 * @param {String} gProcsStatCd gProcsStatCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getProcsSate = async function(gProcsStatCd) {
    // 처리상태 조회하기
    url += "&SCREN_ID=" + "ULDSTF33011.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Check",
        action : "/LnkDisclsApplCorp.do",
        ref : "",
        target : "dts_Check=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const vPROCS_STAT_CD = dts_Check.getCellData(1, "LNK_DISCLS_PROCS_STAT_CD");
    const vPROCS_STAT_NM = dts_Check.getCellData(1, "LNK_DISCLS_PROCS_STAT_NM");
    if (gProcsStatCd === vPROCS_STAT_CD) {
        await $c.win.alert("신청건은  이미 [" + vPROCS_STAT_NM + "] 처리가 되었습니다.");
        // fn_CloseParentReload();
        return false;
    }
    if (gProcsStatCd !== scwin.V_PROCS_CD_4) {
        // 중복처리 체크
        url += "&SCREN_ID=" + "ULDSTF33011.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_Check",
            action : "/LnkDisclsApplCorp.do",
            ref : "",
            target : "dts_Check=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const V_LNK_DISCLS_APPL_TP_NM = dts_Check.getCellData(1, "LNK_DISCLS_APPL_TP_NM");
        const V_LNK_DISCLS_APPL_DD = dts_Check.getCellData(1, "LNK_DISCLS_APPL_DD");
        if (dts_Check.getRowCount() > 0) {
            await $c.win.alert("선택한 자회사는  이미 [" + V_LNK_DISCLS_APPL_TP_NM + "] 신청건으로 승인상태[연계공시적용일(" + V_LNK_DISCLS_APPL_DD + ")] 에 있어 처리 할 수 없습니다.");
            return false;
        }

        // 법인상태 조회하기
        url += "&SCREN_ID=" + "ULDSTF33011.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions2 = {
            id : "sbm_dts_Check",
            action : "/LnkDisclsApplCorp.do",
            ref : "",
            target : "dts_Check=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const vHdcomLstStatCd = dts_Check.getCellData(1, "HDCOM_LIST_STAT_CD");
        const vSumcomLstStatCd = dts_Check.getCellData(1, "SUBCOM_LIST_STAT_CD");
        const vLnkDisclsSubmitCorpYn = dts_Check.getCellData(1, "LNK_DISCLS_SUBMIT_CORP_YN");
        if (vHdcomLstStatCd !== 'Y') {
            await $c.win.alert("지주회사는 상장법인이 아니므로  처리할 수 없습니다.");
            return false;
        }
        if (vSumcomLstStatCd !== 'Y') {
            await $c.win.alert("자회사는 상장법인이 아니므로  처리할 수 없습니다.");
            return false;
        }
        if (dts_Item.getCellData(1, "LNK_DISCLS_APPL_TP_CD") === '1') {
            if (vLnkDisclsSubmitCorpYn === 'Y') {
                await $c.win.alert("신청자회사는 이미 연계공시 등록법인이므로  처리할 수 없습니다.");
                return false;
            }
        }
    }
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @param {*} pType pType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function(pType) {
    if (scwin.gLinkApplSeq === "") {
        await $c.win.alert("[대상]을 선택하세요.");
        return false;
    }
    if (edt_LNK_DISCLS_APPL_DD.getValue() === "") {
        await $c.win.alert("[연계공시적용일]을 입력하세요.");
        edt_LNK_DISCLS_APPL_DD.focus();
        return false;
    }
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (vCurDate >= edt_LNK_DISCLS_APPL_DD.getValue()) {
        await $c.win.alert("[연계공시적용일]을 현재일이후로 입력하세요.");
        edt_LNK_DISCLS_APPL_DD.focus();
        return false;
    }
    if (txb_REJ_RSN.getValue() !== "") {
        await $c.win.alert("거부시에만 [거부사유]를 입력하세요.");
        txb_REJ_RSN.focus();
        return false;
    }
    let gMSG = '';
    if (pType === 'R') {
        scwin.gPROCS_CD = scwin.V_PROCS_CD_2;
        gMSG = '검토';
    } else if (pType === 'A') {
        scwin.gPROCS_CD = scwin.V_PROCS_CD_3;
        gMSG = '승인';
    }
    let rtn = confirm(gMSG + '처리 하시겠습니까?');
    if (rtn === 1) {
        if (await scwin.getProcsSate(scwin.gPROCS_CD) === false) {
            return false;
        } else {
            trs_Approve.KeyName = "toinb_dataid4";
            // [전환검토] trs_Approve.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
            // const sbmParams = {
            //     LNK_DISCLS_APPL_SEQ : scwin.gLinkApplSeq,
            //     PROCS_CD : scwin.gPROCS_CD,
            //     LNK_DISCLS_APPL_DD : $c.stf.getObjectValue(edt_LNK_DISCLS_APPL_DD),
            //     EMP_NO : js_emp_no
            // };
            const sbmOptions = {
                id : "sbm_trs_Approve",
                action : "/LnkDisclsApplCorp.do",
                ref : "dts_Item",
                target : "trs_Approve=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }
    }
};

/**
 * @method
 * @name reject
 * @description reject 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reject = async function() {
    if (scwin.gLinkApplSeq === "") {
        await $c.win.alert("[대상]을 선택하세요.");
        return false;
    }
    if (txb_REJ_RSN.getValue() === "") {
        await $c.win.alert("[거부사유]를 입력하세요.");
        txb_REJ_RSN.focus();
        return false;
    }
    scwin.gPROCS_CD = scwin.V_PROCS_CD_4;
    let rtn = confirm('거부처리 하시겠습니까?');
    if (rtn === 1) {
        if (await scwin.getProcsSate(scwin.gPROCS_CD) === false) {
            return false;
        } else {
            trs_Approve.KeyName = "toinb_dataid4";
            // [전환검토] trs_Approve.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
            // const sbmParams = {
            //     LNK_DISCLS_APPL_SEQ : scwin.gLinkApplSeq,
            //     PROCS_CD : scwin.V_PROCS_CD_4,
            //     LNK_DISCLS_APPL_DD : $c.stf.getObjectValue(edt_LNK_DISCLS_APPL_DD),
            //     EMP_NO : js_emp_no,
            //     REJ_RSN : $c.stf.getObjectValue(txb_REJ_RSN)
            // };
            const sbmOptions = {
                id : "sbm_trs_Approve",
                action : "/LnkDisclsApplCorp.do",
                ref : "dts_Item",
                target : "trs_Approve=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name showProcButton
 * @description 처리버튼 생성여부
 * @param {String} pProcsDepCd pProcsDepCd
 * @param {String} pLinkListStatCd pLinkListStatCd
 * @returns {void}
 * @hidden N
 */
scwin.showProcButton = function(pProcsDepCd, pLinkListStatCd) {
    scwin.gLinkListStatCd = pLinkListStatCd;
    btn_Revwr.setBackgroundImage("../img/btn_study_d.gif");
    btn_Revwr.setDisabled(true);
    btn_Approve.setBackgroundImage("../img/btn_approval_d.gif");
    btn_Approve.setDisabled(true);
    btn_Reject.setBackgroundImage("../img/btn_reject2_dis.gif");
    btn_Reject.setDisabled(true);
    panel_Button.hide();

    // alert(gDutyYn+","+gDutyChrg+","+gDepCd+","+pProcsDepCd);

    if (scwin.gLinkApplSeq !== '') {
        // 1:미처리,2:검토,3:승인,4:거부
        if (scwin.gLinkListStatCd === '1' || scwin.gLinkListStatCd === '2') {
            panel_Button.show("");
            if (scwin.gLinkListStatCd === '1') {
                if (scwin.gDutyYn === 'Y' || scwin.gDutyChrg === 'Y' || scwin.gDepCd === pProcsDepCd) {
                    // 팀장 및 당번 권한일때만 보임
                    btn_Revwr.setBackgroundImage("../img/btn_study.gif");
                    btn_Revwr.setDisabled(false);
                    btn_Reject.setBackgroundImage("../img/btn_reject2.gif");
                    btn_Reject.setDisabled(false);
                }
            } else if (scwin.gLinkListStatCd === '2') {
                // 팀장 및 당번 권한일때만 보임, 팀장  : 09,   부서장: 40, 팀원: 03
                if ((scwin.gDutyYn === 'Y' || scwin.gDutyChrg === 'Y') || (scwin.gJobTitle === '09' && scwin.gDepCd === pProcsDepCd)) {
                    btn_Approve.setBackgroundImage("../img/btn_approval.gif");
                    btn_Approve.setDisabled(false);
                    btn_Reject.setBackgroundImage("../img/btn_reject2.gif");
                    btn_Reject.setDisabled(false);
                }
            }
        }
    }
};

/**
 * @method
 * @name getParentValue
 * @description get Parent Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.getParentValue = function() {
    scwin.gLinkApplSeq = $c.frame.path("../").scwin.gLinkApplSeq;
};

/**
 * @method
 * @name revwr
 * @description revwr 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.revwr = async function() {
    await scwin.save('R');
};

/**
 * @method
 * @name approve
 * @description approve 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.approve = async function() {
    await scwin.save('A');
};
